class TrieNode:
    def __init__(self):
        self.children = {}
        self.count = 0

class Trie:
    def __init__(self):
        self.root = TrieNode()
        self.L = 18  # Since node labels ≤ 1e5, need up to 17 bits (2¹⁷ > 1e5)

    def insert(self, num):
        node = self.root
        for i in range(self.L, -1, -1):
            bit = (num >> i) & 1
            if bit not in node.children:
                node.children[bit] = TrieNode()
            node = node.children[bit]
            node.count += 1

    def remove(self, num):
        node = self.root
        for i in range(self.L, -1, -1):
            bit = (num >> i) & 1
            node = node.children[bit]
            node.count -= 1

    def max_xor(self, num):
        node = self.root
        res = 0
        for i in range(self.L, -1, -1):
            bit = (num >> i) & 1
            toggled = 1 - bit
            if toggled in node.children and node.children[toggled].count > 0:
                res |= (1 << i)
                node = node.children[toggled]
            else:
                node = node.children.get(bit, node)
        return res

def maximumGeneticDifference(parents, queries):
    from collections import defaultdict

    n = len(parents)
    tree = [[] for _ in range(n)]
    root = -1
    for i, p in enumerate(parents):
        if p == -1:
            root = i
        else:
            tree[p].append(i)

    # Group queries by node for local processing
    node_queries = defaultdict(list)
    for idx, (node, val) in enumerate(queries):
        node_queries[node].append((val, idx))

    ans = [0] * len(queries)
    trie = Trie()

    def dfs(u):
        trie.insert(u)
        for val, idx in node_queries[u]:
            ans[idx] = trie.max_xor(val)
        for v in tree[u]:
            dfs(v)
        trie.remove(u)

    dfs(root)
    return ans
